const fs = require("fs");
const path = require("path");
const root = "/w/node_modules/agents";
const pkg = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8"));
function typesWithImports(entry) {
  const exp = pkg.exports[entry];
  if (!exp) return null;
  const file = path.join(root, exp.types);
  let text = fs.readFileSync(file, "utf8");
  for (const m of text.matchAll(/from "(\.\.?\/[^"]+)\.js"/g)) {
    const dep = path.join(path.dirname(file), m[1] + ".d.ts");
    if (fs.existsSync(dep)) text += "\n" + fs.readFileSync(dep, "utf8");
  }
  return text;
}
const react = typesWithImports("./react");
const client = typesWithImports("./client");
const union = /type AgentTransport = "cf-websocket" \| "capnweb";/;
const option = /transport\?: AgentTransport\b/;
const onUseAgent = option.test(react) && union.test(react);
const onAgentClient = option.test(client) && union.test(client);
if (!onUseAgent || !onAgentClient) {
  console.error("FAIL: agents " + pkg.version + " useAgent/AgentClient options have no transport option (useAgent=" + onUseAgent + ", AgentClient=" + onAgentClient + ")");
  process.exit(1);
}
console.log("OK: agents " + pkg.version + ' useAgent and AgentClient take transport?: "cf-websocket" | "capnweb"');

